S = 1;                   // semaphore variable

// ---- entry section ----
wait(S) {
    while (S <= 0);      // locked, spin here
    S = S - 1;           // take the lock
}

// ---- critical section ----
read(c);
c++;
write(c);

// ---- exit section ----
signal(S) {
    S = S + 1;           // release the lock
}

lock = false;               // false = free, true = held

// ---- entry section ----
acquire() {                 // this whole block is atomic
    while (lock == true);   // held by someone, spin here
    lock = true;            // take the lock
}

// ---- critical section ----
read(c);
c++;
write(c);

// ---- exit section ----
release() {
    lock = false;           // only the owner releases it
}
